using System;using System.IO;using System.Linq;using System.Diagnostics;using System.Collections.Generic;using System.Threading;
namespace GearLab {
 public static class Transmission60Tests {
  public static int Run(string folder){Directory.CreateDirectory(folder);var checks=new List<string>();var failures=new List<string>();var previews=new List<object>();Action<bool,string> check=(ok,msg)=>{if(ok)checks.Add(msg);else failures.Add(msg);};Action<double,double,double,string> near=(v,w,t,msg)=>check(!double.IsNaN(v)&&Math.Abs(v-w)<=t,msg+" actual="+Engine.N(v));int workers=CADKernel.StartedWorkers;try{
   var worm=Engine.Starter(5);worm.WormStarts=2;worm.Ratio=20;worm.InputRpm=300;worm.InputTorque=.5;var w=Engine.Calculate(worm);check(w.Valid,"worm valid");near(w.Actual,20,1e-10,"worm ratio z2/starts");near(w.Engineering.OutputRpm,-15,1e-10,"worm signed speed");near(w.Engineering.Centre,25,1e-10,"worm centre m(q+z2)/2");near(w.Engineering.LeadAngle,Math.Atan(.2),1e-12,"worm lead");near(w.Engineering.InputPower,5*Math.PI,1e-10,"worm power");near(w.Engineering.OutputPower,w.Engineering.OutputTorque*Math.Abs(w.Engineering.OutputRpm)*Math.PI/30,1e-10,"worm energy balance");check(!w.Engineering.SelfLockEstimate,"worm two-start no self lock at mu=.08");worm.WormStarts=1;worm.WormDiameterFactor=30;check(Engine.Calculate(worm).Engineering.SelfLockEstimate,"friction model self lock");worm.WormStarts=0;check(!Engine.Calculate(worm).Valid,"zero starts rejected");
   var bevel=Engine.Starter(6);bevel.Module=2;bevel.InputTorque=.5;var b=Engine.Calculate(bevel);check(b.Valid,"bevel valid");near(b.Engineering.Cone1,Math.Atan(.5),1e-12,"bevel cone1 independently atan1/2");near(b.Engineering.Cone1+b.Engineering.Cone2,Math.PI/2,1e-12,"bevel apex angles close");near(b.Engineering.ConeDistance,Math.Sqrt(2000),1e-10,"bevel cone length Pythagoras");near(b.Engineering.OutputRpm,-15,1e-10,"bevel output direction");bevel.Thickness=50;check(!Engine.Calculate(bevel).Valid,"bevel overwide face rejected");
   var rack=Engine.Starter(12);rack.InputRpm=60;rack.InputTorque=.35;rack.Efficiency=.7;var rr=Engine.Calculate(rack);check(rr.Valid,"rack valid");near(rr.Engineering.LinearSpeed,20*Math.PI,1e-10,"rack speed circumference/s");near(rr.Engineering.OutputForce,24.5,1e-10,"rack force N not Nm");near(rr.Engineering.OutputForce*rr.Engineering.LinearSpeed/1000,rr.Engineering.OutputPower,1e-10,"rack power");rack.RackTravel=rack.RackLength;check(!Engine.Calculate(rack).Valid,"rack engagement end margin");
   var rv=Engine.Calculate(Engine.Starter(7));check(rv.Valid,"RV valid: "+string.Join(";",rv.Errors));near(rv.Actual,64,1e-10,"RV Nabtesco 1+3*21");near(rv.Engineering.SpeedGain,1.0/64,1e-12,"RV same direction");var dp=Engine.Starter(8);var dr=Engine.Calculate(dp);check(dr.Valid,"compound planets valid");near(dr.Actual,3.5,1e-12,"Willis ring fixed");dp.FixedMember=1;near(Engine.Calculate(dp).Engineering.SpeedGain,-.4,1e-12,"Willis carrier fixed");dp.FixedMember=3;dp.InputRpm=100;dp.SecondInputRpm=-10;dr=Engine.Calculate(dp);near(dr.Engineering.OutputRpm,75/3.5,1e-12,"two-input Willis");check(double.IsNaN(dr.Engineering.OutputTorque),"two-input torque not invented");dp.PlanetTeeth=17;check(!Engine.Calculate(dp).Valid,"compound phase incompatible rejected");
   var reactions=TransmissionAudit.BearingReactions(100,10,0,40);near(reactions[0],75,1e-12,"bearing lever reaction1");near(reactions[1],25,1e-12,"bearing lever reaction2");rack=Engine.Starter(12);rack.RackPosition=10;near(TransmissionSizing.RackPhase(rack,0),0,1e-12,"rack zero phase preserves design position");
   dp=Engine.Starter(8);dp.FixedMember=3;dp.InputRpm=0;dp.SecondInputRpm=60;dr=Engine.Calculate(dp);dr.Model=CadBuilder.Build(dr);near(dr.Engineering.OutputRpm,300.0/7,1e-10,"Willis stationary sun with rotating ring");near(dr.TransmissionMotions["T_SUN"].Gain,0,1e-12,"stationary sun animation");near(dr.TransmissionMotions["T_RING"].Gain,1,1e-12,"second input animation independent of first rpm");near(dr.TransmissionMotions["T_OUTPUT_SHAFT"].Gain,5.0/7,1e-12,"two-input output shaft animation");
   var mp=Engine.Starter(11);mp.InputRpm=480;var mr=Engine.Calculate(mp);near(mr.Engineering.OutputRpm,-96,1e-10,"magnetic p1/p2");check(mr.Notes.Any(x=>x.Contains("FEA")),"magnetic torque qualification");
   for(int kind=0;kind<13;kind++){var p=Engine.Starter(kind);var r=Engine.Calculate(p);check(r.Valid,"starter "+kind+": "+string.Join(";",r.Errors));var sw=Stopwatch.StartNew();r.Model=CadBuilder.Build(r);sw.Stop();check(r.Model.Valid,"model "+kind+": "+string.Join(";",r.Model.Errors));var meshes=r.Model.Parts.Select(x=>SceneMesher.Build(x,CancellationToken.None)).ToList();check(meshes.All(x=>x.SignedVolume()>1e-6),"positive preview volumes "+kind);check(meshes.All(x=>x.Points.All(v=>MechanismCad.Finite(v.X)&&MechanismCad.Finite(v.Y)&&MechanismCad.Finite(v.Z))),"finite preview "+kind);foreach(var part in r.Model.Parts)check(PartMotion.Bind(r,part).At(1.1,0).HasInverse,"finite invertible motion "+part.Id);var again=ReleaseSupport.Parse(ReleaseSupport.Serialize(p));check(ReleaseSupport.Serialize(again)==ReleaseSupport.Serialize(p),"project roundtrip "+kind);previews.Add(new{Kind=kind,Milliseconds=sw.Elapsed.TotalMilliseconds,Parts=r.Model.Parts.Count,Triangles=meshes.Sum(x=>x.Triangles)});File.WriteAllText(Path.Combine(folder,"type-"+kind+".gear.json"),ReleaseSupport.Serialize(p));if(kind>=5){File.WriteAllText(Path.Combine(folder,"type-"+kind+".assembly.json"),CADDocument.Serializer().Serialize(TransmissionExport.Spec(r.Model)));var printable=PrintExport.Select(r.Model,null);PrintExport.Zip(printable,Path.Combine(folder,"type-"+kind+"-stl.zip"));}}
   check(CADKernel.StartedWorkers==workers,"all previews and STL without native worker");
  }catch(Exception ex){failures.Add(ex.ToString());}File.WriteAllText(Path.Combine(folder,"transmissions60-results.json"),CADDocument.Serializer().Serialize(new{Passed=failures.Count==0,Checks=checks.Count,Failures=failures,Previews=previews,Workers=CADKernel.StartedWorkers-workers}));Console.WriteLine("Transmission60: "+checks.Count+" checks, "+failures.Count+" failures");return failures.Count==0?0:1;}
 }
}
